var orders = app.MapGroup("/api/orders").WithTags("Orders");

orders.MapGet("", () => Results.Ok(Array.Empty<OrderDto>()));
orders.MapGet("/{id:int}", (int id) =>
    id == 0 ? Results.NotFound() : Results.Ok(new OrderDto(id, "pending")));
orders.MapPost("", (CreateOrderDto dto) =>
    Results.Created($"/api/orders/99", new OrderDto(99, dto.Status)));
orders.MapPatch("/{id:int}", (int id, PatchOrderDto patch) => Results.Ok());
orders.MapDelete("/{id:int}", (int id) => Results.NoContent());

record OrderDto(int Id, string Status);
record CreateOrderDto(string Status);
record PatchOrderDto(string? Status);

[ApiController]
[Route("api/[controller]")]
public class InvoicesController : ControllerBase
{
    [HttpGet("{id:guid}")]
    public ActionResult<InvoiceDto> Get(Guid id) =>
        Ok(new InvoiceDto(id, 100m));

    [HttpPost]
    public ActionResult<InvoiceDto> Create(CreateInvoiceDto dto)
    {
        var created = new InvoiceDto(Guid.NewGuid(), dto.Amount);
        return CreatedAtAction(nameof(Get), new { id = created.Id }, created);
    }
}

record InvoiceDto(Guid Id, decimal Amount);
record CreateInvoiceDto(decimal Amount);

